/**
 * Shared primitive types for src/core and the platform contracts.
 * CONTRACT: owned by the lead. Subagents do not edit this file; report needed changes instead.
 * No react-native / expo imports anywhere under src/core.
 */

export type Unsubscribe = () => void;

/** Opaque timer handle (number in browsers/Hermes, Timeout object in Node). */
export type TimerHandle = unknown;

/** Injectable time source so state machines and the two-peer simulation are deterministic. */
export interface Clock {
  now(): number;
  setTimeout(fn: () => void, ms: number): TimerHandle;
  clearTimeout(handle: TimerHandle): void;
}

export const systemClock: Clock = {
  now: () => Date.now(),
  setTimeout: (fn, ms) => setTimeout(fn, ms),
  clearTimeout: (handle) => clearTimeout(handle as ReturnType<typeof setTimeout>),
};

export type LogLevel = 'debug' | 'info' | 'warn' | 'error';

/** Log payloads are flat primitives on purpose: easy to redact, easy to export. */
export type LogData = Record<string, string | number | boolean | null | undefined>;

/**
 * Sink for the diagnostics ring buffer.
 * Implementations MUST redact secrets: any key matching /secret|passphrase|password|key|mac|proof|nonce|token/i
 * is replaced by "[redacted]" (see src/core/diagnostics). Callers must still never log such values.
 */
export interface Logger {
  log(level: LogLevel, tag: string, message: string, data?: LogData): void;
}

export const nullLogger: Logger = { log: () => undefined };
